entries[121817] = { ["name"] = "Kämpferische Weisheit", ["text"] = "Außerhalb des Kampfs pendelt sich Euer Chi auf 2 ein, anstatt erschöpft zu werden.\n\nAlle 15 Sek. setzt Euer nächster Einsatz von 'Tigerklaue' zusätzlich 'Schadensumleitung' ein und verursacht 30% mehr Schaden.\n\nSchadensumleitung\nNebelwirker ( Nebelwirkermönch )\nStößt negatives Chi aus Eurem Körper, was Euch um (120% der Zaubermacht) Gesundheit heilt und einem Gegner innerhalb von 20 Metern 25% des geheilten Werts als Naturschaden zufügt.\n\nBraumeister, Windläufer\nStößt negatives Chi aus Eurem Körper, was Euch um (120% der Zaubermacht) Gesundheit heilt und einem Gegner innerhalb von 20 Metern 10% des geheilten Werts als Naturschaden zufügt. [ Schadensumleitung : Entzieht all Euren heilenden Sphären positives Chi, um die Heilung durch 'Schadensumleitung' zu erhöhen ] [ Schadensumkehr : Erzeugt [(120% der Zaubermacht) + 30] Chi. ]" }
entries[121818] = { ["name"] = "Stampede", ["text"] = "40 Meter Reichweite\nSofort 5 min Abklingzeit\nBeschwört alle Eure Begleiter, die daraufhin Euer aktuelles Ziel 40 Sek. lang angreifen. Auf diese Weise herbeigerufene Begleiter verursachen in Arenen und auf Schlachtfeldern nur 25% ihres normalen Schadens." }
entries[121820] = { ["name"] = "Obsidiannachtschwinge", ["text"] = "Wirken in 1.5 sek.\nVerwandelt Euch in eine Obsidiannachtschwinge, wodurch Ihr sehr schnell fliegen und einen Verbündeten auf Eurem Rücken tragen könnt. Das ist ein Flugreittier.\n\"Wenn man nicht mehr rennen kann, kriecht man halt, und wenn man nicht mehr kriechen kann, sucht man sich jemanden, der einen trägt.\"\nWerbt einen Freund" }
