entries[122707] = { ["name"] = "Schallschutz", ["text"] = "Unbegrenzte Reichweite\nSofort\nErzeugt einen ' Schallschutz '-Bereich im Umkreis von 0 Metern um den Zaubernden. In diesem Bereich befindliche Kreaturen sind vor der Fähigkeit ' Kraft und Schwung ' des kaiserlichen Wesirs Zor'lok geschützt." }
entries[122708] = { ["name"] = "Großes Expeditionsyak", ["text"] = "Wirken in 1.5 sek.\nRuft ein großes Expeditionsyak herbei, komplett mit Grummel-Begleitern für all Eure Geschäftsbedürfnisse!\n\"Diese Lasttiere sind dafür bekannt, dass sie mehr als das Fünffache ihres Gewichtes tragen und mehrere Tage ohne Nahrung oder Wasser auskommen können.\"\nVerkäufer:\nOnkel Dickehose\nZone:\nKun-Lai-Gipfel\nKosten:\n120000" }
entries[122710] = { ["name"] = "Wachsamkeit", ["text"] = "40 Meter Reichweite\nSofort 2 min Abklingzeit\nRichtet Euren schützenden Blick auf ein Gruppen- oder Schlachtzugsmitglied und leitet 12 Sek. lang 30% des von ihm erlittenen Schadens auf Euch um.\n\nWährend der Dauer von 'Wachsamkeit' unterliegt Eure Fähigkeit 'Spott' keiner Abklingzeit und Angriffe gegen das Ziel versetzen Euch 12 Sek. lang in einen Wutzustand." }
