entries[123075] = { ["name"] = "Todesengel", ["text"] = "Sofort\nKlaxxiverstärkung\nVerliehen von Kil'ruk dem Windschnitter.\n\nBefinden sich mindestens 2 Gegner innerhalb von 10 Metern von Euch, setzt Kil'ruk 'Schnitt' ein.\n\nKann nur einmal pro Minute eintreten.\n\nEs kann immer nur eine Klaxxiverstärkung aktiv sein. Funktioniert nur in der Schreckensöde.\n\nSchnitt\nKil'ruk fügt Euren Gegnern mit mächtigen Hieben sofort Schaden und im Verlauf von 10 Sek. weiteren Blutungsschaden zu." }
